// 웹 테스트 빌드 PWA(기획지시 2026-10-31 PWA테스트빌드): /play·/dev를 휴대폰 홈 화면 앱처럼 전체 화면으로 시험하기 위한 것.
// 정식 배포 채널이 아니다(정식은 Godot 네이티브). 오프라인 플레이·푸시·스토어 배포 없음. DEV_LOGIN=1 환경에서만 열린다.
import { PLAY_PAGE } from "./playpage.mjs";
import { TEST_PAGE } from "./devpage.mjs";

// 아이콘(성좌 모양 가안, 테스트용). 192·512·maskable 512·apple-touch 180
const ICONS = {
 "icon-192": "",
 "icon-512": "",
 "maskable-512": "",
 "apple-touch-icon": ""
};

// 서비스 워커: 정적 셸(페이지·매니페스트·아이콘)은 버전별 캐시, 카드 이미지(내용 해시 파일명)는 따로 캐시.
// 전투·계정 통신(/v1/*, 실시간 연결)은 캐시하지 않는다. 새 버전은 페이지가 허락할 때(판 밖)만 적용(skipWaiting은 메시지로만).
const SW = `const V='__V__',SHELL='shell-'+V,IMG='img-v1';
const PRE=['/play','/dev','/manifest.webmanifest','/icons/icon-192.png','/icons/icon-512.png','/icons/maskable-512.png','/icons/apple-touch-icon.png'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(SHELL).then(c=>c.addAll(PRE)))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k.startsWith('shell-')&&k!==SHELL).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('message',e=>{if(e.data==='skipWaiting')self.skipWaiting()});
self.addEventListener('fetch',e=>{const r=e.request;if(r.method!=='GET')return;const u=new URL(r.url);
 if(u.origin===location.origin){if(PRE.includes(u.pathname))e.respondWith(caches.open(SHELL).then(c=>c.match(u.pathname).then(m=>m||fetch(r))));return}
 if(u.pathname.includes('/storage/v1/object/public/'))e.respondWith(caches.open(IMG).then(c=>c.match(u.href).then(m=>m||fetch(u.href,{mode:'cors'}).then(res=>{if(res.ok)c.put(u.href,res.clone());return res}).catch(()=>fetch(r)))));
});`;

// 페이지 공통 머리말(매니페스트·iOS 홈 화면 앱 설정)과 스크립트(서비스 워커 등록, 새 버전 띠, 설치 버튼 상태)
const HEAD = `<link rel="manifest" href="/manifest.webmanifest"><meta name="theme-color" content="#0d1020">
<link rel="apple-touch-icon" href="/icons/apple-touch-icon.png"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="apple-mobile-web-app-title" content="성좌">`;
// 새 버전 띠: 판 진행 중(PWA_BUSY)에는 숨기고, 누를 때만 새 워커로 바꿔 새로고침(강제 새로고침 없음)
const CLIENT = `<div id="pwaUpd" hidden style="position:fixed;left:50%;bottom:max(12px,env(safe-area-inset-bottom));transform:translateX(-50%);z-index:150;background:#2b5fd0;color:#fff;border-radius:99px;padding:8px 18px;font:600 14px system-ui,sans-serif;box-shadow:0 6px 20px rgba(0,0,0,.5);cursor:pointer">새 버전이 있어요 · 새로고침</div>
<script>
window.PWA={ver:'__V__',prompt:null,standalone:matchMedia('(display-mode: standalone)').matches||matchMedia('(display-mode: fullscreen)').matches||navigator.standalone===true,
 ios:/iP(hone|ad|od)/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),
 install:function(){var p=PWA.prompt;if(!p)return;p.prompt();p.userChoice.then(function(){PWA.prompt=null;PWA.changed()})},changed:function(){if(window.onPwaChange)window.onPwaChange()}};
addEventListener('beforeinstallprompt',function(e){e.preventDefault();PWA.prompt=e;PWA.changed()});
addEventListener('appinstalled',function(){PWA.prompt=null;PWA.changed()});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').then(function(reg){var bar=document.getElementById('pwaUpd'),go=false;
 var check=function(){var busy=window.PWA_BUSY&&window.PWA_BUSY();bar.hidden=!(reg.waiting&&navigator.serviceWorker.controller&&!busy)};
 bar.onclick=function(){if(!reg.waiting)return;go=true;reg.waiting.postMessage('skipWaiting')};
 navigator.serviceWorker.addEventListener('controllerchange',function(){if(go)location.reload()});
 setInterval(check,2000);setInterval(function(){reg.update().catch(function(){})},60000);check()}).catch(function(){});
</script>`;

function hash(str) {  // FNV-1a 32비트: 페이지·워커가 바뀌면 버전(캐시 이름)이 바뀜
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i += 1) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(36);
}
export const PWA_VERSION = hash(PLAY_PAGE + TEST_PAGE + SW + HEAD + CLIENT + Object.values(ICONS).join(""));

export function withPwa(html) {
  return html.replace("<head>", `<head>${HEAD}`).replace("</body>", `${CLIENT.replaceAll("__V__", PWA_VERSION)}</body>`);
}
export const PWA_PLAY = withPwa(PLAY_PAGE);
export const PWA_DEV = withPwa(TEST_PAGE);
export const SW_SOURCE = SW.replace("__V__", PWA_VERSION);
export const MANIFEST = JSON.stringify({
  name: "성좌 결투", short_name: "성좌", id: "/play", start_url: "/play", scope: "/",
  display: "fullscreen", display_override: ["fullscreen", "standalone"], orientation: "landscape",
  background_color: "#0d1020", theme_color: "#0d1020", lang: "ko",
  icons: [
    { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
    { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
    { src: "/icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }
  ]
});
export function iconBytes(name) {
  const b64 = ICONS[name];
  if (!b64) return null;
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}
